begin;

with input_items as (
  select *
  from jsonb_to_recordset('[]'::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset('[{"id": "cb0ef2e7-3a80-588d-beef-10998a5ce5e7", "feature_slug": "purchase-transactions", "title": "Current Production Status", "content": "### System Health\n- **Total Transactions**: 0 (system ready, awaiting production use)\n- **Total Line Items**: 0 (infrastructure in place)\n- **Trigger Status**: All triggers deployed and active\n- **Integration**: Connected to currency, tier, and mission systems\n- **Queue Status**: Empty (no pending processing)\n\n### Schema Status\n- **Tables**: ✅ Both purchase_ledger and purchase_items_ledger exist\n- **Relationships**: ✅ Foreign keys properly configured\n- **RLS**: ✅ Enabled on both tables\n- **Triggers**: ✅ Currency, tier, and mission triggers active\n- **Indexes**: ✅ Performance indexes in place\n\n### Integration Validation\n- **Currency Integration**: ✅ Trigger connects to wallet system\n- **Tier Integration**: ✅ Trigger connects to tier queue\n- **Mission Integration**: ✅ Dual triggers for manual/auto missions\n- **Store Attribution**: ✅ Store attribute resolution functional\n\n### API Readiness\n- **RPC Functions**: Need to create `create_purchase_via_api()` function\n- **User Resolution**: Need to create `find_user_by_identifier()` function\n- **Validation Logic**: Need to implement amount calculations validation\n- **Error Handling**: Need comprehensive error responses\n\nThe purchase transaction system demonstrates **production-ready infrastructure** with comprehensive event-driven integration, dual-table granularity for flexible analysis, and scalable processing architecture suitable for high-volume transaction processing across multiple channels and business models.\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Purchase_Transaction.md#L1214 Current Production Status", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "cf876d243969b0c59d817effd71c0cba376eff01d6a18a83464bd22c115676a9", "truncated": false}, "is_active": true}, {"id": "3f4d2842-0bdd-535a-b481-e46f3e752d90", "feature_slug": "purchase-transactions", "title": "7. Business Rules", "content": "**Rule:** `status = ''completed''` is the single trigger point for all loyalty operations — currency award, tier evaluation, and mission progress all fire on this transition.\n**Example:** Transaction inserted with `status = ''pending''` → no loyalty impact. Status updated to `''completed''` → triggers fire.\n\n**Rule:** Refunds create new debit records; originals are never modified (append-only ledger).\n**Example:** Original TXN001 (credit, 1,500 THB, 15 points awarded). Refund creates TXN001-REF (debit, 1,500 THB). Net sales = 0, net currency = 0.\n\n**Rule:** Partial refunds create proportional debit records. Currency reversal uses the original earn rates stored in metadata.\n**Example:** 1,500 THB purchase earned 15 points during a 3x promotion. 500 THB partial refund → reverses 5 points (using original 3x rate), not the current 1x rate.\n\n**Rule:** Processing method determines currency routing. Queue is non-blocking (~1 min delay), direct is synchronous (immediate), skip bypasses currency entirely.\n**Example:** High-volume merchant uses `queue` for POS transactions. VIP lounge uses `direct` for instant gratification.\n\n**Rule:** Transaction status and payment status are independent. Either can advance without the other.\n**Example:** E-commerce order: `payment_status = ''paid''` but `status = ''processing''` (payment captured, awaiting fulfillment). Loyalty operations don''t fire until `status = ''completed''`.\n\n**Rule:** Empty `seller_id` means B2C transaction. Populated `seller_id` enables dual-perspective evaluation — buyer and seller each get independent currency and tier processing.\n**Example:** Distributor sells to retailer → distributor earns seller-tier points, retailer earns buyer-tier points.\n\n**Rule:** `transaction_number` must be unique per merchant. Duplicates are rejected.\n**Example:** POS sends TXN001 twice → second insert fails, preventing double-counting.\n\n**Rule:** Line-item product hierarchy enables granular earn multipliers. Category, brand, and SKU-level rates apply to individual lines before transaction-wide multipliers apply to the remainder.\n**Example:** Transaction has shoes (3x category) and socks (1x). Shoes earn 3x on their line total, socks earn base rate. Birthday bonus (2x) applies to the remainder.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/purchase-transactions.md#L215 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "aa7cb38b775ac78f54a737e602593db7988cbfbf539e6db96f8b730bc57d7876", "truncated": false}, "is_active": true}, {"id": "68581dcb-2e56-50e3-8a14-6aa9abf96b4b", "feature_slug": "purchase-transactions", "title": "3. Configuration Reference", "content": "### Transaction Processing\n\n| Setting | What it controls | Values | Default |\n|---|---|---|---|\n| `processing_method` | Currency award routing on completion | `queue`, `direct`, `skip` | `queue` |\n| `earn_currency` | Whether this transaction qualifies for currency awards | `true` / `false` | `true` |\n\n### Status Mapping (E-commerce Integration)\n\n| E-commerce event | Maps to `status` | Maps to `payment_status` |\n|---|---|---|\n| Payment captured | `completed` (Option A: payment-based trigger) | `paid` |\n| Payment captured + fulfilled | `completed` (Option B: fulfillment-based trigger) | `paid` |\n| Payment refunded | `refunded` (creates debit record) | `refunded` |\n| Order cancelled | `cancelled` | `voided` |\n\n### Amount Calculation\n\n| Level | Formula |\n|---|---|\n| Line item | `(quantity × unit_price) - line_discount + line_tax = line_total` |\n| Transaction | `SUM(line_totals) - discount_amount + tax_amount = final_amount` |", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/purchase-transactions.md#L41 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "6b7fc2eee7e6d93a74e314d034f18575c9c81ec6182f6f8d8dd171bf0bcceb35", "truncated": false}, "is_active": true}, {"id": "6ab60a00-e840-5493-aee3-d69a93d8dbff", "feature_slug": "purchase-transactions", "title": "Admin Member 360 Purchase History RPC", "content": "**Status:** Deployed to Production  \n**Implementation Date:** May 6, 2026  \n**Migration:** `frontline_admin_be_rpcs`\n\n`admin_get_user_purchases(p_user_id uuid, p_limit int default 10, p_offset int default 0, p_search text default null, p_sort text default ''date_desc'')` returns the Member 360 purchase/receipt history envelope:\n\n```json\n{ \"success\": true, \"data\": { \"items\": [], \"total\": 0, \"totals\": { \"bill_count\": 0, \"points\": 0, \"amount\": 0 } } }\n```\n\nRows include purchase id, transaction number/date, store id/name/code/channel label, amount, item count, awarded points/tickets, payment method, status, batch id, and image URLs. Auth is admin-only: caller must resolve a merchant via `get_current_merchant_id()` and have an active `admin_users` row for that merchant; `p_user_id` must belong to the same merchant.\n\n`bff_admin_search_members(p_query, p_limit, p_store_id)` now supports member search by `external_user_id` and `member_code`, returns persona/user metadata and points balance, and optionally filters members to those with a purchase or redemption at `p_store_id`.\n\n`bff_admin_create_member(p_phone, p_firstname, p_lastname, p_fullname, p_email, p_birth_date, p_external_user_id, p_member_code, p_user_type, p_persona_id, p_id_card, p_line_id, p_gender)` creates members through a SECURITY DEFINER admin BFF. It resolves merchant via `get_current_merchant_id()`, requires an active `admin_users` row for the caller, checks duplicate phone/email/external user ID/member code/LINE ID within the merchant, and returns `{ success, data: { user_id } }`. Frontends should use this RPC instead of direct `user_accounts` inserts.\n\n---\n\n*Document Version: 1.0*  \n*Last Updated: October 2024*  \n*System: Supabase CRM - Purchase Transaction System*", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Purchase_Transaction.md#L1291 Admin Member 360 Purchase History RPC", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c41a6ec9b4c0c1da204020df884bad9963873d5c3ed666ca73235b1c26bcb1f7", "truncated": false}, "is_active": true}, {"id": "c743e6b8-3162-5bab-974e-553e4a0ed289", "feature_slug": "purchase-transactions", "title": "Core Tables and Structure", "content": "### 1. purchase_ledger Table\nThis table defines transaction headers with complete financial and operational metadata. Key fields include:\n\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | Unique transaction identifier used throughout system |\n| `merchant_id` | uuid | Merchant ownership establishing data isolation boundaries |\n| `transaction_number` | text | Human-readable unique identifier per merchant for customer reference |\n| `transaction_date` | timestamptz | When transaction occurred (business date, may differ from created_at) |\n| `user_id` | uuid | Customer who made the purchase (buyer perspective) |\n| `seller_id` | uuid | Seller user (FK to `user_accounts.id`, typically `user_type = ''seller''`, nullable). Powers the seller self-service completion flow. FK is `NOT VALID` so 26 historical orphan rows were grandfathered; new and updated rows are enforced. |\n| `store_id` | text | Store code from store_master where purchase occurred |\n| `total_amount` | numeric | Sum of all line items before discounts/tax |\n| `discount_amount` | numeric | Total discounts applied to transaction |\n| `tax_amount` | numeric | Total tax charged |\n| `final_amount` | numeric | Net amount after discounts and tax (what customer actually paid) |\n| `status` | enum | Transaction lifecycle state (see Status Model section below) |\n| `payment_status` | text | Payment processing state (pending/authorized/paid/refunded) |\n| `record_type` | enum | ''credit'' for normal purchases, ''debit'' for refunds |\n| `processing_method` | text | Currency award routing: ''queue'' (async), ''direct'' (immediate), ''skip'' (none) |\n| `earn_currency` | boolean | Whether this transaction qualifies for currency awards (default true) |\n| `currency_processed_at` | timestamptz | When currency calculation completed (nullable until processed) |\n| `currency_error` | text | Error message if currency processing failed |\n| `transaction_source` | text | Channel identifier (online/in-store/mobile/kiosk) |\n| `api_source` | text | Source system name (POS/mobile_app/ecommerce/admin) |\n| `external_ref` | text | Reference to external system''s transaction ID for reconciliation |\n| `notes` | text | Additional transaction notes or context |\n| `created_at` | timestamptz | Record creation timestamp (system time) |\n| `updated_at` | timestamptz | Last modification timestamp |\n| `skip_cdc` | boolean | When true, row is excluded from CDC publication (never emits Kafka event). Used for data migration and historical imports. Default false. |\n| `completed_by_user_id` | uuid | `user_accounts.id` of the actor that flipped the row to `completed` (NULL for system/admin/API). Stamped on every transition by writers and the rollup helper. |\n| `completed_by_source` | text | Free-form source tag explaining how the row was completed: `seller_self_service`, `seller_line_item_completion`, `api_external`, `system_bulk_import`, `refund_flow`, `marketplace_claim`, `historical_backfill`, or `parent_cascade`. |\n| `completed_at` | timestamptz | Timestamp of the transition to `completed`. **Invariant** (forward-looking): `status = ''completed''` ⇒ `completed_at IS NOT NULL`. Historical pre-2026-05-10 rows may have NULL completed_at. |\n\n**Unique Constraint**: `transaction_number` must be unique per merchant for customer-facing reference (NOT enforced — see \"Transaction Number Disambiguation\" below).\n\n**Transaction Number Disambiguation**: Historical data contains duplicate `(merchant_id, transaction_number)` pairs. Seller self-service functions disambiguate by also filtering on `seller_id = caller`. If multiple pending rows still match, the BFFs return `AMBIGUOUS_TRANSACTION_NUMBER`.\n\n### 2. purchase_items_ledger Table\nThis table stores individual line items within each transaction with SKU-level detail. Key fields include:\n\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | Unique line item identifier |\n| `transaction_id` | uuid | References parent transaction in purchase_ledger |\n| `merchant_id` | uuid | Merchant context for data isolation |\n| `sku_id` | uuid | References product_sku_master for product variant detail |\n| `quantity` | numeric | Number of units purchased (supports decimals for weight-based products) |\n| `unit_price` | numeric | Price per unit before discounts |\n| `discount_amount` | numeric | Discount applied to this line (nullable, defaults 0) |\n| `tax_amount` | numeric | Tax charged on this line (nullable, defaults 0) |\n| `line_total` | numeric | Final line amount: (quantity × unit_price) - discount + tax |\n| `status` | enum | Per-line lifecycle (same `purchase_status` enum as parent). Default `''pending''`. Cascades to `''completed''` when the parent flips, via `trg_purchase_complete_cascade_items`. Sellers can also flip individual lines via `bff_seller_complete_purchase_items`. |\n| `completed_by_user_id` | uuid | `user_accounts.id` of the actor that completed this line (NULL for cascade or default writes). |\n| `completed_by_source` | text | Source tag, parallel to `purchase_ledger.completed_by_source`. Adds `parent_cascade` for cascaded rows. |\n| `completed_at` | timestamptz | Per-line completion timestamp. |\n| `created_at` | timestamptz | Line item creation timestamp |\n| `updated_at` | timestamptz | Last modification timestamp |\n\n**Relationship**: Multiple items belong to one transaction (one-to-many)\n\n**Status Cascade Rules**:\n- Parent → children: parent flipping to `completed` cascades to all children via a **statement-level** trigger (one fire per UPDATE statement, regardless of row count).\n- Children → parent: rolled up **inline** by the seller line-item BFF (no row-level trigger on this high-volume table). Reusable rollup is exposed as `fn_recompute_purchase_status(p_purchase_id, p_completed_by_user_id, p_completed_by_source)`.\n- Bulk admin scripts can opt out of the cascade by setting `SET LOCAL app.purchase_cascade_skip = ''on'';` before their UPDATE.\n\n### 3. Integration Tables\n\n#### user_accounts (purchase-relevant fields)\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | User identifier (buyer in most transactions) |\n| `merchant_id` | uuid | Merchant context |\n| `user_type` | enum | ''buyer'' or ''seller'' - determines perspective in calculations |\n| `tier_id` | uuid | Current tier affecting earn rates and multipliers |\n| `persona_id` | uuid | Business profile affecting pricing and eligibility |\n\n#### product_sku_master (line item detail source)\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | SKU identifier referenced by line items |\n| `product_id` | uuid | Parent product linking to category/brand hierarchy |\n| `sku_code` | text | Human-readable SKU identifier |\n| `price` | numeric | Standard retail price for reference |\n\n#### store_master (location context)\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | Store identifier |\n| `store_code` | varchar | Human-readable code stored in purchase_ledger.store_id |\n| `merchant_id` | uuid | Store ownership |", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Purchase_Transaction.md#L24 Core Tables and Structure", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "10f7f947c80b5a4e0b68eec4a31a370e06fde469dfd4a026b8fbdea3855147ad", "truncated": false}, "is_active": true}, {"id": "5ce2deba-ab04-5b91-9b77-7916b29bf42b", "feature_slug": "purchase-transactions", "title": "Function Categories & Architecture", "content": "### 🎯 CORE FUNCTIONS (Business Logic Orchestrators)\n\n#### `create_purchase_via_api(merchant_id, user_identifier, store_code, transaction_data, items)`\n**Purpose**: Primary transaction creation function for external API integration  \n**Category**: Core Business Logic Orchestrator  \n**Returns**: JSONB with transaction details and processing status  \n**Security**: SECURITY DEFINER with merchant validation\n\n**Processing Flow**:\n1. **User Resolution**: Calls `find_user_by_identifier()` to resolve user_id from phone/email/line_id\n2. **Transaction Number Generation**: Creates unique identifier via sequence\n3. **Header Creation**: Inserts purchase_ledger with all metadata\n4. **Items Creation**: Loops through items array, inserts to purchase_items_ledger\n5. **Trigger Cascade**: Database triggers fire automatically on completion\n6. **Response**: Returns transaction_id and processing indicators\n\n**Validation**:\n- User must exist in merchant\n- Store must exist (if provided)\n- SKUs must exist for line items\n- Amounts must be positive\n- Transaction number uniqueness enforced\n\n#### `find_user_by_identifier(merchant_id, identifier, identifier_type)`\n**Purpose**: User lookup supporting multiple identifier types  \n**Category**: Helper Function  \n**Returns**: UUID of user or NULL if not found\n\n**Supported Identifier Types**:\n- `''phone''`: Matches phone, tel, or phone_number fields\n- `''email''`: Matches email field\n- `''line_id''`: Matches line_id field\n- `''user_id''`: Direct UUID lookup\n- `''cognito_sub''`: Cognito integration\n\n**Used By**: API functions to resolve external identifiers to internal user_id\n\n#### Seller Self-Service Functions (BFF)\n\nEnd-user functions for sellers (users with `user_accounts.user_type = ''seller''`) to read and complete their assigned purchases without going through the admin panel. All three resolve the seller via `auth.uid()` against the user JWT and validate `user_type = ''seller''` before doing any work.\n\n##### `bff_seller_get_purchase_by_transaction_number(p_transaction_number text) → jsonb`\n\n**Purpose**: Read a purchase header + line items the calling seller is assigned to.\n**Auth**: end-user JWT (no admin context needed).\n**Lookup**: `(merchant_id, transaction_number, seller_id = auth.uid())`.\n**Returns**: `{ purchase: {...}, items: [...] }` where each item includes its own `status` and `completed_*`. Returns `AMBIGUOUS_TRANSACTION_NUMBER` if multiple rows match (legacy duplicate `transaction_number`).\n\n##### `bff_seller_complete_purchase_by_transaction_number(p_transaction_number text) → jsonb`\n\n**Purpose**: Flip the whole pending purchase to `completed` in one shot.\n**Lookup**: `(merchant_id, transaction_number, seller_id = auth.uid(), status = ''pending'')`.\n**Effect**: Single UPDATE on the parent stamps `status = ''completed''`, `completed_by_user_id = caller`, `completed_by_source = ''seller_self_service''`, `completed_at = NOW()`. The cascade trigger handles all children atomically — no per-row work in this function.\n**Errors**: `PURCHASE_NOT_FOUND`, `AMBIGUOUS_TRANSACTION_NUMBER`, `FORBIDDEN_NOT_SELLER`.\n\n##### `bff_seller_complete_purchase_items(p_transaction_number text, p_line_item_ids uuid[]) → jsonb`\n\n**Purpose**: Flip selected line items to `completed`. Used when the seller fulfils items one at a time.\n**Validation**: Every supplied `id` must belong to this purchase + merchant; otherwise rejected with `INVALID_LINE_ITEMS` and the offending ids. Parent must be `pending` or `processing`; else rejected with `INVALID_TRANSITION`.\n**Effect**:\n1. One UPDATE flips only the `pending` lines among `p_line_item_ids` (idempotent on already-completed lines).\n2. Lines are stamped with `completed_by_user_id = caller`, `completed_by_source = ''seller_self_service''`.\n3. Inline rollup via `fn_recompute_purchase_status` — if every child is now `completed`, parent is flipped and stamped with `completed_by_source = ''seller_line_item_completion''`.\n**Returns**: `{ items_completed, items_skipped, completed_ids, skipped_ids, parent_completed, parent_status }`.\n\n### ⚙️ PROCESSING FUNCTIONS (Currency & Tier Integration)\n\n#### `trigger_process_purchase_currency()`\n**Purpose**: Routes completed purchases to currency calculation  \n**Category**: Trigger Function  \n**Execution**: AFTER INSERT OR UPDATE ON purchase_ledger\n\n**Activation Condition**:\n```\nIF (status = ''completed'' AND earn_currency = true) THEN\n  CASE processing_method\n    WHEN ''queue'' THEN enqueue_wallet_transaction()\n    WHEN ''direct'' THEN post_wallet_transaction()\n    WHEN ''skip'' THEN NULL\n  END\nEND IF\n```\n\n#### `trigger_tier_eval_on_purchase()`\n**Purpose**: Routes completed purchases to tier evaluation  \n**Category**: Trigger Function  \n**Execution**: AFTER INSERT OR UPDATE ON purchase_ledger\n\n**Activation Condition**:\n```\nIF (status = ''completed'') THEN\n  PERFORM queue_tier_evaluation(\n    user_id,      -- Or seller_id for seller-type users\n    merchant_id,\n    ''purchase'',\n    NEW.id\n  )\nEND IF\n```\n\n**Deduplication**: 30-second window prevents queue flooding\n\n#### `trigger_mission_evaluation_realtime()` / `queue_mission_evaluation_batch()`\n**Purpose**: Routes purchases to mission evaluation based on activation type  \n**Category**: Trigger Functions  \n**Execution**: AFTER INSERT OR UPDATE ON purchase_ledger\n\n**Routing Logic**:\n- Manual missions → Real-time evaluation\n- Auto missions → Queue for batch processing\n\n### 🔧 HELPER FUNCTIONS (Supporting Utilities)\n\n#### `get_purchase_details(transaction_id, merchant_id)`\n**Purpose**: Retrieve complete purchase with line items  \n**Category**: Query Helper  \n**Returns**: JSONB with transaction and items array\n\n**Data Structure**:\n```json\n{\n  \"transaction\": {\n    \"id\": \"uuid\",\n    \"transaction_number\": \"TXN20241019001\",\n    \"total_amount\": 1500,\n    \"final_amount\": 1350,\n    \"status\": \"completed\"\n  },\n  \"items\": [\n    {\n      \"sku_code\": \"COFFEE-L\",\n      \"quantity\": 2,\n      \"unit_price\": 120,\n      \"line_total\": 240\n    }\n  ],\n  \"currency_awarded\": {\n    \"points\": 13,\n    \"tickets\": []\n  }\n}\n```\n\n#### `calculate_purchase_totals(items_array)`\n**Purpose**: Calculate transaction totals from line items  \n**Category**: Calculation Helper  \n**Returns**: JSONB with total_amount, tax, discount calculations\n\n**Used By**: API functions to validate incoming transaction data\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Purchase_Transaction.md#L815 Function Categories & Architecture", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "7e7ad911e287c8e8f03bc5a642ef6d2b3a3f4b8e7602e30930c125af10e364d3", "truncated": false}, "is_active": true}, {"id": "747044e4-08b4-532c-9a4f-e8f9f5137dda", "feature_slug": "purchase-transactions", "title": "2. Key Concepts", "content": "**Purchase Ledger** — The transaction header table (`purchase_ledger`). Stores totals, status, payment info, user/store context, and processing flags. Each row is one transaction with a unique `transaction_number` per merchant. Example: `TXN20241019000123` for a 1,500 THB purchase at Store A.\n\n**Purchase Items Ledger** — The line-item detail table (`purchase_items_ledger`). Each row is one product line within a transaction, linked by `transaction_id`. Stores SKU, quantity, unit price, and line total. Example: 2× Coffee (120 THB each) = 240 THB line total.\n\n**Record Type** — Distinguishes purchases from refunds. `credit` = normal purchase (adds to sales metrics, awards currency). `debit` = refund (subtracts from metrics, reverses currency). Both store positive `final_amount` values — the system negates debits in calculations.\n\n**Transaction Status** — Five-state lifecycle controlling when business logic fires:\n- `pending` — created, not finalized, editable\n- `processing` — payment authorized, locked from editing\n- `completed` — finalized, triggers currency + tier + mission cascade\n- `cancelled` — aborted before completion, no loyalty impact\n- `refunded` — reversed after completion, triggers currency reversal + tier re-evaluation\n\n**Payment Status** — Independent financial tracking (text field, not enum): `pending`, `authorized`, `paid`, `failed`, `refunded`, `voided`. A transaction can be `status=completed` while `payment_status=authorized` (fulfillment done, settlement pending), or `payment_status=paid` while `status=processing` (payment captured, fulfillment in progress).\n\n**Processing Method** — Controls how currency calculation is routed on completion:\n- `queue` — async via PGMQ, non-blocking, currency appears within ~1 minute\n- `direct` — synchronous, immediate balance update, slower checkout\n- `skip` — no currency processing (test transactions, internal transfers)\n\n**Final Amount** — The net amount the customer actually paid: `total_amount - discount_amount + tax_amount`. This is the value used for currency calculation, tier metrics, and mission progress.\n\n**Buyer / Seller Perspective** — `user_id` tracks the buyer (customer); `seller_id` tracks the seller (distributor/merchant staff). B2C transactions typically have `seller_id = NULL`. Both perspectives can independently earn currency and progress tiers.\n\n**External Reference** — The `external_ref` field links to the source system''s transaction ID (Shopify order number, POS receipt number) for reconciliation and refund correlation.\n\n**Transaction Source / API Source** — Two-level channel tracking. `transaction_source` = high-level channel (`online`, `in-store`, `mobile`, `kiosk`). `api_source` = specific system (`POS`, `shopify`, `lazada`, `admin`).", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/purchase-transactions.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "656ed4a275ea41ad66d89fa58018c27c69b3f34d0d921313dec97a9e3166a4e4", "truncated": false}, "is_active": true}, {"id": "70912ec8-84a5-5884-be3a-263f106fc20c", "feature_slug": "purchase-transactions", "title": "6a. For Customer Success / Support", "content": "**Elevator pitch:** \"Every time a customer makes a purchase, the system can automatically award points, progress their tier, and advance their missions. Transactions come in from POS, online stores, or receipt uploads — they''re all tracked in one ledger with full refund history.\"\n\n**Top support questions:**\n\n| Question | Answer |\n|---|---|\n| \"Customer didn''t receive points after purchase\" | Check: (1) `status` must be `completed`, (2) `earn_currency` must be `true`, (3) `processing_method` — if `queue`, currency may take up to 1 minute; if `skip`, no currency by design. Check `currency_processed_at` and `currency_error` fields. |\n| \"Customer wants a refund reversal\" | Refunds create a new debit record — original transaction stays intact. Currency reversal is automatic and proportional using the original earn rates. |\n| \"Points from receipt upload are wrong\" | Check the line items added during approval — product-specific earn multipliers depend on correct SKU assignment. Preview Points shows the estimate before approval. |\n| \"Duplicate transaction detected\" | The system enforces unique `transaction_number` per merchant. If a duplicate is submitted, approval is blocked. Check if the same receipt was uploaded twice. |\n| \"Tier didn''t upgrade after big purchase\" | Tier evaluation is queued with 30-second dedup. Check if `final_amount` meets tier threshold, and whether the evaluation window (rolling/fixed/anniversary) includes this transaction. |", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/purchase-transactions.md#L125 6. Perspectives / 6a. For Customer Success / Support", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "dacdf6ee1afca7ec93d93ed42fe270789c8c54c432e3518f268103baeacff770", "truncated": false}, "is_active": true}, {"id": "2863bd3d-e761-5323-bdc4-c8e5f43d7121", "feature_slug": "purchase-transactions", "title": "1. Overview", "content": "Purchase transactions are the primary earning trigger in the loyalty ecosystem — every completed purchase can award currency (points/tickets), advance tier progression, and increment mission progress. The system captures both transaction headers and line-item details in a dual-table architecture, enabling granular product-level earn rules (e.g., 3x points on shoes, 2x on beverages) alongside transaction-wide multipliers.\n\nTransactions flow in from external systems — POS terminals, e-commerce platforms (Shopify, Lazada), mobile apps, admin-approved receipt uploads — not from a dedicated admin form. The system treats purchases as immutable audit records: once completed, a transaction is never modified. Refunds create separate debit records that reverse currency awards proportionally, preserving the full history for reconciliation and analytics.\n\nKey characteristics: (1) **append-only ledger** — credit records for purchases, debit records for refunds, originals never mutated; (2) **flexible processing** — queue (async, high-throughput), direct (immediate gratification), or skip (no currency); (3) **multi-system trigger cascade** — a single completion event independently fires currency calculation, tier evaluation, and mission progress; (4) **dual perspective** — same transaction can track both buyer (B2C) and seller (B2B) for distributor networks.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/purchase-transactions.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5f630de2df4ffec6c6322a4b3415d295184b2bb7b98e8c333b6ec45026996e9a", "truncated": false}, "is_active": true}, {"id": "1b0a5933-c8a5-50dd-854b-3859734a059d", "feature_slug": "purchase-transactions", "title": "8. Related Features", "content": "| Feature | Connection to Purchase Transactions |\n|---|---|\n| Currency | Completed purchases trigger currency award via `calc_currency_for_transaction()`. Refunds trigger proportional reversal. See `Currency.md`. |\n| Tier | Completed purchases contribute to tier metrics (sales = `SUM(final_amount)`, orders = `COUNT(*)`). Triggers `queue_tier_evaluation()`. See `Tier.md`. |\n| Mission | Purchase conditions evaluate against transaction amount and line-item product filters. See `Mission.md`. |\n| Store Classification | `store_id` resolves to store attribute sets for location-based earn multipliers and mission conditions. See `Store_Attribute_Classification.md`. |\n| Activity/Earning | Earn factors (multipliers by product, category, brand, store, tier) are evaluated against purchase line items. See `Activity_Based_Earning.md`. |\n| Receipt Upload | Admin-approved receipt uploads create purchase records via `bff_approve_receipt_upload()`. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/purchase-transactions.md#L241 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a421e27d17eb8533fe442ae3c16f5dd9bff75d4472aa99259480662e40f079ef", "truncated": false}, "is_active": true}, {"id": "a9fe693d-ed53-52b4-a6dd-27d1efc6526d", "feature_slug": "purchase-transactions", "title": "Integration Patterns", "content": "### Currency System Integration\n\n**Award Flow**:\n1. Purchase completes → Currency calculation triggered\n2. System calls `calc_currency_for_transaction(transaction_id)`\n3. Evaluates earn factors against transaction and line items\n4. Creates wallet_ledger entries with `source_type = ''purchase''`, `source_id = transaction_id`\n5. Updates user balances (points and/or tickets)\n\n**Reversal Flow**:\n1. Refund debit record created → Reversal detection\n2. System queries original wallet_ledger via source_id\n3. Reads calculation metadata (rates, multipliers used)\n4. Creates proportional reversal entries\n5. Deducts from user balances\n\n**Metadata Preservation**: Original calculation stored in wallet_ledger.metadata for accurate reversals when rates change\n\n### Tier System Integration\n\n**Metric Contribution**:\n- Sales metric: `SUM(final_amount)` with credit/debit handling\n- Orders metric: `COUNT(*) WHERE final_amount > 0`\n- Both respect user_type (buyer uses user_id, seller uses seller_id)\n\n**Evaluation Trigger**:\n- Queue-based with 30-second deduplication\n- Evaluates within time windows (rolling/fixed/anniversary)\n- Can trigger upgrades or affect maintenance calculations\n\n### Mission System Integration\n\n**Progress Tracking**:\n- Missions with purchase conditions evaluate on completion\n- Product filters match against line items\n- Amount filters check transaction final_amount\n- Store filters check via store attribute sets\n\n**Dual Processing Paths**:\n- Manual missions: Real-time evaluation\n- Auto missions: Batch evaluation every 30 seconds\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Purchase_Transaction.md#L1046 Integration Patterns", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "af78f420446d5edb7dbdf8da1fa6d3e6d519b2647db6d307e3e0b929c96eb374", "truncated": false}, "is_active": true}, {"id": "ae7e00ee-e3bf-545b-8ba2-f74a3b353f1b", "feature_slug": "purchase-transactions", "title": "Status State Design & E-commerce Integration", "content": "### Simplified Status Model (Current Design)\n\n**Decision**: Use single `status` field without separate fulfillment dimension\n\n**Rationale**:\n- Optimized for instant-fulfillment business models\n- Reduces complexity of three-dimensional status tracking (order/payment/fulfillment)\n- Clear trigger point for loyalty operations\n- Suitable for fuel, retail, in-store, digital, and service transactions\n\n**Status Field**: Combines transaction lifecycle and fulfillment into unified state\n**Payment Status**: Separate field for financial settlement tracking\n**Fulfillment**: Not tracked separately - assumed instant or included in `completed` status\n\n### E-commerce Platform Integration\n\nWhen integrating with platforms using multi-dimensional status (like Shopify):\n\n**Shopify''s Three Status Dimensions**:\n- **Order Status**: Open / Archived / Canceled (workflow state)\n- **Payment Status**: Pending / Authorized / Paid / Refunded (financial state)\n- **Fulfillment Status**: Unfulfilled / Fulfilled (logistics state)\n\n**These statuses are independent** - one changing doesn''t automatically trigger others. They''re coordinated through Shopify''s business workflow logic.\n\n**Mapping Strategy to Your CRM**:\n\n**Trigger Point Decision** (Business Policy):\n\n**Option A - Payment-Based** (Recommended for most):\n- Shopify webhook: `payment_status = ''Paid''` → Set your `status = ''completed''`\n- Awards currency when payment captured, regardless of shipping\n- **Pros**: Immediate customer gratification, higher engagement\n- **Cons**: May need reversals if order cancelled after payment\n- **Best for**: Digital goods, low return rates, customer experience priority\n\n**Option B - Fulfillment-Based** (Conservative):\n- Shopify webhook: `payment_status = ''Paid'' AND fulfillment_status = ''Fulfilled''` → Set your `status = ''completed''`\n- Awards currency only when customer receives goods\n- **Pros**: Fewer reversals, cleaner accounting\n- **Cons**: Delayed gratification (days/weeks), lower engagement\n- **Best for**: High return rate categories, long shipping times\n\n**Option C - Hybrid**:\n- Award partial currency on payment, remainder on fulfillment\n- Award on payment but extend reversal grace period to match return policy\n\n**Refund Handling**:\n- Shopify webhook: `payment_status = ''Refunded''` → Create debit record with `status = ''refunded''`\n- Triggers currency reversal automatically\n\n**Coordination Note**: The integration logic in your webhook handlers coordinates Shopify''s multi-status to your single status based on your business rules. Shopify''s statuses don''t automatically trigger each other - your code interprets their states to determine your status transitions.\n\n### Future Extension: Fulfillment Tracking\n\nIf merchants require delivery tracking, consider:\n\n**Option 1**: Add fulfillment columns to purchase_ledger\n- Simple extension for basic tracking\n- Fields: fulfillment_status, shipped_at, delivered_at, tracking_number\n\n**Option 2**: Create purchase_fulfillment table\n- Separate table for complex fulfillment workflows\n- One-to-one with purchase_ledger\n- Enables multiple shipments per order\n\n**Option 3**: External fulfillment system\n- Use `external_ref` to link to shipping platform\n- Track delivery state externally\n- Keep CRM focused on loyalty, not logistics\n\n**Current Decision**: Not implemented - simplified model for transaction-based loyalty use cases\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Purchase_Transaction.md#L969 Status State Design & E-commerce Integration", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a856da31a15f50d103c395f797dfe447a428d13eab705045125bee04c9fbd794", "truncated": false}, "is_active": true}, {"id": "6ada2003-c2df-577a-a562-63e926f36b23", "feature_slug": "purchase-transactions", "title": "Purchase Transaction Domain Reference", "content": "**Keywords:** purchase, transaction, order, payment, refund, credit, debit, line item, SKU, purchase ledger, purchase items, final amount, status, completed, processing method, store, seller, wallet ledger code, POS discount\n**Source:** `Purchase_Transaction.md`\n|---|---|---|\n| Function | Parameters | Returns | Lines |\n|---|---|---|---|\n| `create_purchase_via_api(merchant_id, user_identifier, store_code, transaction_data, items)` | Merchant, user identifier, store, transaction data, items array | JSONB with transaction_id and processing status | 783–803 |\n| `get_purchase_details(transaction_id, merchant_id)` | `transaction_id (uuid)`, `merchant_id (uuid)` | Transaction + items array + currency awarded | 866–895 |\n| `bff_seller_get_purchase_by_transaction_number(p_transaction_number)` | `transaction_number` | `{ purchase, items[] }` for the seller-assigned purchase | see \"Seller Self-Service Functions\" |\n| `bff_seller_complete_purchase_by_transaction_number(p_transaction_number)` | `transaction_number` | Flips whole purchase to completed; cascade fires for line items | see \"Seller Self-Service Functions\" |\n| `bff_seller_complete_purchase_items(p_transaction_number, p_line_item_ids[])` | `transaction_number`, array of line item UUIDs | Flips selected lines; rolls parent to completed if all lines done | see \"Seller Self-Service Functions\" |\n| Function | Purpose |\n|---|---|\n| `fn_recompute_purchase_status(p_purchase_id, p_completed_by_user_id, p_completed_by_source)` | Idempotent children → parent rollup. Used by the seller line-item BFF and reusable by any future caller that flips child status outside the BFF. |\n| `trigger_cascade_purchase_complete_to_items()` | Backs `trg_purchase_complete_cascade_items` — statement-level parent → children cascade with transition tables. |\n**Key Business Rules (summary):**\n- `status = ''completed''` is the trigger for currency award, tier evaluation, and mission progress\n- Refunds create new debit records (never modify the original credit record)\n- `processing_method`: `queue` (async, default), `direct` (immediate), `skip` (no currency)\n- `record_type`: `credit` for purchases, `debit` for refunds; calculations negate debits\n- Buyer perspective via `user_id`, seller perspective via `seller_id` (FK to `user_accounts.id`, `NOT VALID` over 26 historical orphans)\n- Staff POS point-discount orders store the frontline wallet reference in `purchase_ledger.wallet_ledger_code`. Reconciliation compares this value to `wallet_ledger.code` and checks `purchase_ledger.discount_amount` against `wallet_ledger.discount_amount`.\n- **Completion stamping invariant** (forward-looking): every transition to `status = ''completed''` populates `completed_by_user_id`, `completed_by_source`, `completed_at`. Sources include `seller_self_service`, `seller_line_item_completion`, `api_external`, `system_bulk_import`, `marketplace_claim`, `refund_flow`, `parent_cascade`, `historical_backfill`.\n- **Status cascade**: parent → children handled by statement-level trigger `trg_purchase_complete_cascade_items` (one fire per UPDATE, transition-table join). Children → parent rolled up inline via `fn_recompute_purchase_status` — there is no row-level trigger on `purchase_items_ledger`.\n- **Line-item status**: `purchase_items_ledger.status` mirrors the parent. New writers (`api_create_purchase`, `bulk_insert_purchases_with_items`, `claim_marketplace_order`) create children with the parent''s status from the start so the cascade trigger never has to flip them later.", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/purchase-transaction.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "800df02e2f84551b14912f641c8217e3ea0c4ff09c12dfe523c1710c45bcc97b", "truncated": false}, "is_active": true}, {"id": "862816d5-ed54-5336-b905-e9e25d07b2fd", "feature_slug": "purchase-transactions", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n| Config | Expected behavior |\n|---|---|\n| `status = ''completed''`, `earn_currency = true`, `processing_method = ''queue''` | Currency awarded within ~1 minute via queue |\n| `status = ''completed''`, `earn_currency = true`, `processing_method = ''direct''` | Currency awarded immediately in same transaction |\n| `status = ''completed''`, `processing_method = ''skip''` | No currency awarded regardless of `earn_currency` |\n| `status = ''completed''`, `earn_currency = false` | No currency awarded regardless of `processing_method` |\n| `status = ''pending''` or `''processing''` | No currency, no tier eval, no mission progress |\n| `status = ''cancelled''` | No loyalty impact; record preserved for audit |\n| `record_type = ''debit''` (refund) | Currency reversed proportionally using original earn rates |\n| `seller_id` populated | Both buyer and seller evaluated for tier/currency independently |\n\n**Status transition assertions:**\n\n- ASSERT: `pending` → `processing` → `completed` is the normal flow\n- ASSERT: `completed` → `refunded` creates a new debit record, does not modify original\n- ASSERT: `completed` → `pending` is invalid (cannot uncomplete)\n- ASSERT: `cancelled` → `completed` is invalid (cannot resurrect)\n- ASSERT: `cancelled` and `refunded` are terminal states\n\n**Business rules as assertions:**\n\n- ASSERT: On `status = ''completed''`, three independent triggers fire: currency, tier, mission\n- ASSERT: Currency reversal uses the original transaction''s earn rates stored in `wallet_ledger.metadata`, not current rates\n- ASSERT: Partial refund creates a debit record with proportional `final_amount`; currency reversal is proportional\n- ASSERT: `transaction_number` is unique per merchant — duplicate INSERT fails\n- ASSERT: `final_amount = total_amount - discount_amount + tax_amount`\n- ASSERT: Line item `line_total = (quantity × unit_price) - discount_amount + tax_amount`\n- ASSERT: Tier evaluation has 30-second dedup — rapid consecutive purchases don''t flood the queue\n- ASSERT: Mission progress evaluates product filters against `purchase_items_ledger` line items\n\n**Status model (two independent tracks):**\n\n| Track | Field | Values | Meaning |\n|---|---|---|---|\n| Transaction | `status` | `pending` → `processing` → `completed` | Business lifecycle |\n| Transaction (terminal) | `status` | `cancelled`, `refunded` | Final states, no further transitions |\n| Payment | `payment_status` | `pending`, `authorized`, `paid`, `failed`, `refunded`, `voided` | Financial settlement (independent of transaction status) |\n\n**Error states to test:**\n\n- Purchase with non-existent `user_id` → creation fails\n- Purchase with non-existent `store_id` → creation fails or store context missing\n- Line items referencing non-existent `sku_id` → creation fails\n- Currency processing failure → `currency_error` populated, `currency_processed_at` remains null\n- Concurrent purchases by same user → each processed independently, queue dedup prevents tier evaluation flooding\n- Refund amount exceeding original `final_amount` → should be blocked\n- Receipt upload with duplicate `transaction_number` → preview warns, approve blocks", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/purchase-transactions.md#L125 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "67d4ef0a862120eafaf464ba12bea0d672ecd2137f1e1b1cd2efb8f2a9adda3d", "truncated": false}, "is_active": true}, {"id": "07d4b3d6-4704-5560-bfcf-ce3c1000b686", "feature_slug": "purchase-transactions", "title": "5. Member Experience", "content": "**Repo:** `Rocket-CRM/loyalty-user`\n\n**Route map:**\n\n| Page / Component | Current route | Data source |\n|---|---|---|\n| History Drawer | Bottom-sheet from Homepage/Profile | `bff_get_purchase_history(p_filter, p_limit, p_offset)` |\n\nMembers do not create purchases directly in the app. Purchases are recorded by external systems (POS, e-commerce) or via receipt upload approval. Members see their purchase history in the History Drawer.\n\n### 5a. View Purchase History\n\n1. Member opens **History Drawer** (from Homepage or Profile) → selects the **Purchases** tab\n2. Sub-filter chips: **\"Ordered\"** / **\"Reviewed\"**\n3. Each row shows: order number as title, item count, transaction amount, date, and currency earned (points/tickets badges with +/- signs)\n4. Infinite scroll pagination for long histories\n\n### 5b. Purchase-Triggered Notifications\n\n1. When a purchase completes and currency is awarded, the member sees the updated points balance on the Homepage **Profile Card**\n2. Currency history (viewable in the **Currency** tab of History Drawer) shows the earn entry linked to the purchase with `source_type = ''purchase''`", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/purchase-transactions.md#L101 5. Member Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e9a974c3ef53dce1797f4bff43ba8bff85fa6914c2ffa201050ba455483033f9", "truncated": false}, "is_active": true}, {"id": "f3fb9667-7a67-5b08-a7e0-df1479c481a9", "feature_slug": "purchase-transactions", "title": "6b. For Marketing", "content": "**Value proposition:** Purchase transactions close the loyalty loop — customers buy, earn points automatically, see their tier progress, and are motivated to buy again. The system supports any sales channel (in-store POS, e-commerce, mobile) and awards currency in near-real-time, giving customers instant gratification that reinforces the purchase-earn-redeem cycle.\n\n**Use-case stories:**\n\n1. **Fuel station chain** — Every pump transaction sends purchase data via POS API. Currency awarded within 1 minute (queue method). Members see points on the app before leaving the station. Tier upgrades based on monthly spend happen automatically.\n\n2. **Fashion retailer with Shopify** — Online orders trigger purchase creation on payment capture. Product-level earn rates mean premium categories earn 3x points. Refunds auto-reverse the exact proportional currency — no manual adjustment needed.\n\n3. **Distributor network** — B2B transactions track both buyer and seller. The buyer earns points for purchasing; the distributor earns separate points for selling. Both progress through independent tier ladders.\n\n4. **FMCG brand with receipt uploads** — Members photograph store receipts and submit via the app. Admin reviews, adds line items with correct SKUs, and approves. Product-specific earn rates apply to each verified line item. The preview step shows estimated points before committing.\n\n**Metrics merchants care about:** Transaction volume by channel, average transaction value, currency award rate (points per THB), refund rate, time-to-currency (purchase → points in wallet).\n\n**Differentiators to highlight:**\n- **Any-channel ingestion** — POS, Shopify, Lazada, receipt uploads, and custom API all feed into one ledger\n- **Near-real-time earning** — queue method delivers currency within ~1 minute; direct method is instant\n- **Product-level granularity** — different earn rates for different SKUs, categories, and brands in the same transaction\n- **Automatic refund reversal** — proportional currency clawback using original earn rates, no manual intervention", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/purchase-transactions.md#L125 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "purchase-transactions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "411b94e640f4761846dc256844cb89cd8d8308c4f2eee702e745065bbaf9f7ce", "truncated": false}, "is_active": true}, {"id": "aa5d128e-60e1-55a3-bd0b-2ea81f6ccbc0", "feature_slug": "referral", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin` — **Frontend not yet built.** Routes below are planned.\n\n**Route map:**\n\n| Page name | Planned route | Data source |\n|---|---|---|\n| Referral Settings | `/referral-settings` | `merchant_master` (referral fields), `referral_inviter_limits`, `referral_invitee_outcomes` |\n| Referral Ledger | `/referral-ledger` | `referral_ledger` joined with user data |\n| Mission Settings | `/mission-settings/{id}` | Existing mission UI — add `referral_signup` / `referral_purchase` conditions |\n\n### 4a. Enable the Referral Program\n\n1. From **Referral Settings**, toggle `referral_active` to on\n2. Select activation trigger: \"On Signup\" or \"On First Purchase\"\n3. Save merchant settings\n\n### 4b. Configure Inviter Limits\n\n1. From **Referral Settings**, open the Limits section\n2. Add a row per user type (buyer, seller) with period caps\n3. Leave a period field empty to allow unlimited referrals for that window\n4. Save — limits take effect immediately on new referral signups\n\n### 4c. Configure Invitee Outcomes\n\n1. From **Referral Settings**, open the Outcomes section\n2. Add one or more outcome rows: select type (points/tickets/reward), set amount, optionally set validity period\n3. For ticket outcomes, select the ticket type; for reward outcomes, select the reward item\n4. Save — outcomes apply to the next activated referral\n\n### 4d. Configure Inviter Missions\n\n1. From **Mission Settings**, create or edit a mission\n2. Add a condition of type `referral_signup` or `referral_purchase` with a target count\n3. For milestone missions, set multiple levels with increasing targets\n4. Configure mission rewards (points, tickets, etc.) per the standard mission system\n\n### 4e. View the Referral Ledger\n\n1. From **Referral Ledger**, view all referral relationships\n2. Each row shows: inviter name, invitee name, invite code, signup date, first purchase date (if any)\n3. Filter by date range, activation status\n\n### 4f. Common Admin Mistakes\n\n- Setting `referral_active = true` without configuring any invitee outcomes — invitees get no reward\n- Setting activation trigger to `first_purchase` but expecting immediate inviter mission progress — missions only advance after purchase\n- Configuring limits for `buyer` only when sellers also refer — sellers have no limits applied (unlimited)\n- Creating invitee outcomes but no inviter missions — inviters have no incentive", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/referral.md#L70 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "referral", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "63f615138b23d4ee2f07f4f710e7877f9113f125ab4a4b197043f67578fe91d1", "truncated": false}, "is_active": true}, {"id": "d44c983d-07a7-55ac-9aef-2b068dd3bfc3", "feature_slug": "referral", "title": "7. Business Rules", "content": "**Rule:** One invite code per member per merchant. Codes are generated lazily on first request and permanent — no regeneration, no expiry.\n**Example:** Alice requests her code → \"XK7M2NP1\" created. She requests again next month → same \"XK7M2NP1\" returned.\n\n**Rule:** One referral per invitee per merchant. An invitee cannot be referred by multiple inviters or use different codes.\n**Example:** Bob signs up with Alice''s code → referral recorded. Bob cannot later be credited to Charlie''s code.\n\n**Rule:** Limits are checked at signup time against the inviter''s referral_ledger count for each period. All configured periods must pass — failing any one blocks the referral.\n**Example:** Inviter has daily=2, monthly=10. They''ve sent 1 today but 10 this month → blocked by monthly limit.\n\n**Rule:** Period windows use PostgreSQL date truncation. Daily = midnight-to-midnight, weekly = Sunday-to-Saturday (`date_trunc(''week'')`), monthly = 1st-to-last, yearly = Jan 1-to-Dec 31.\n**Example:** Referral on Saturday at 11pm counts toward this week. A referral on Sunday at 1am starts a new weekly window.\n\n**Rule:** Activation trigger applies to both parties simultaneously. With `signup`, invitee rewards and inviter mission evaluation both happen at registration. With `first_purchase`, both are deferred to the first completed purchase.\n**Example:** Trigger = `first_purchase`. Bob signs up with Alice''s code → ledger created, no rewards yet. Bob buys a product → invitee rewards distributed, Alice''s referral mission advances.\n\n**Rule:** Invitee outcomes are distributed through existing ledger systems. Points/tickets go to `wallet_ledger` with `source_type = ''referral''`. Rewards go to `reward_redemptions_ledger` with `source_type = ''referral''`. Both reference the `referral_ledger.id` for traceability.\n**Example:** Configured outcomes: 100 points + 50 tickets → two wallet_ledger inserts, one with component=bonus (points), one with component=base (tickets).\n\n**Rule:** Inviter rewards are managed entirely by the mission system. No referral-specific reward distribution for inviters exists — the system queues a mission evaluation event, and the mission engine counts qualifying referral_ledger records.\n**Example:** Mission \"Referral Champion\" with milestone at 3 signups. After Alice''s 3rd successful referral, the mission evaluator counts 3 records where `signed_up_at IS NOT NULL` → milestone met → mission reward distributed.\n\n**Rule:** Duplicate prevention operates at multiple layers: unique constraint on `(invitee_user_id, merchant_id)` in referral_ledger, unique constraint on invite_code in referral_codes, and existing-distribution checks before wallet_ledger inserts.\n**Example:** Race condition — two requests process Bob''s signup simultaneously → constraint violation on the second, only one succeeds.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/referral.md#L227 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "referral", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "3feaea43f23221a9b39adc18aa0cd1974189f2da23f2fe34a3235c333a3a013a", "truncated": false}, "is_active": true}, {"id": "d6b7146f-e91b-5a5e-b3fe-1be57046d187", "feature_slug": "referral", "title": "3. Configuration Reference", "content": "### Merchant-Level Settings (on `merchant_master`)\n\n| Setting | What it controls | Values | Default |\n|---|---|---|---|\n| `referral_active` | Master on/off switch for the referral program | `true` / `false` | `false` |\n| `referral_activation_trigger` | When rewards fire for both parties | `signup` / `first_purchase` | — |\n\n### Inviter Limits (per user_type row in `referral_inviter_limits`)\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| User type | Which members this limit row applies to | `buyer` | Required |\n| Max per day | Referrals allowed per calendar day | 2 | Null (unlimited) |\n| Max per week | Referrals allowed per Sun–Sat week | 5 | Null (unlimited) |\n| Max per month | Referrals allowed per calendar month | 10 | Null (unlimited) |\n| Max per year | Referrals allowed per calendar year | 50 | Null (unlimited) |\n| Max lifetime | Total referrals ever | 100 | Null (unlimited) |\n| Priority | Tiebreaker when user matches multiple types | 0 | 0 |\n\n### Invitee Outcomes (rows in `referral_invitee_outcomes`)\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Outcome type | Kind of reward | `points`, `tickets`, or `reward` | Required |\n| Amount | Quantity for points/tickets (null for rewards) | 100 | Null |\n| Entity ID | `ticket_type_id` for tickets, `reward_id` for rewards, null for points | UUID | Null |\n| Valid for days | Expiry period after activation | 30 | Null (no expiry) |\n\n### Inviter Mission Conditions (configured in mission system)\n\n| Condition type | What it counts | Example mission |\n|---|---|---|\n| `referral_signup` | Referral ledger records where `signed_up_at IS NOT NULL` | \"Invite 3 friends to join\" |\n| `referral_purchase` | Referral ledger records where `first_purchase_at IS NOT NULL` | \"Get 5 friends to make first purchase\" |", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/referral.md#L33 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "referral", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "013365a8361fc38510beb9d6f2e6885986dcdd7f7e65bde1168f9b2728eb184a", "truncated": false}, "is_active": true}, {"id": "2eb5c192-638c-5751-8948-9ca6efaa279d", "feature_slug": "referral", "title": "System Requirements & Constraints", "content": "### Functional Requirements\n1. Support unique invite codes per user per merchant\n2. Flexible activation triggers (signup vs purchase)\n3. Configurable limits by user type and time period\n4. Multiple reward types for invitees (points, tickets, rewards)\n5. Mission-based rewards for inviters\n6. Complete audit trail via ledger integration\n7. Duplicate referral prevention\n8. Source tracking across all reward distributions\n\n### Non-Functional Requirements\n1. Code generation within 100ms\n2. Referral processing within 500ms\n3. Support 10,000 concurrent referral signups\n4. Zero duplicate rewards through idempotency\n5. 99.9% availability for invite code generation\n6. Seamless integration without disrupting existing systems\n\n### Constraints\n1. One invite code per user per merchant (simplified UX)\n2. One referral per invitee per merchant (no double-dipping)\n3. PostgreSQL-native solution (Supabase platform)\n4. Must integrate with existing wallet and mission systems\n5. No modification to existing purchase flow\n6. Backward compatible with current infrastructure", "content_format": "markdown", "knowledge_type": "implementation_constraints", "perspectives": ["implementation", "technical", "testing"], "output_uses": ["implementation_brief", "qa_testing", "technical_docs"], "scope": "be", "source_ref": "requirements/Referral.md#L557 System Requirements & Constraints", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "constraints", "feature_slug": "referral", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "bc92ffe1d71fde6386f900c89edce40e7d6a99b0a72ca30950bf80faa24e6cfa", "truncated": false}, "is_active": true}, {"id": "3b3c6d5b-a5f7-54cb-9c72-48165106eed5", "feature_slug": "referral", "title": "Core Tables and Structure", "content": "### 1. merchant_master Table (Extended)\nAdditional fields for referral configuration:\n\n| Field | Type | Purpose |\n|-------|------|---------|\n| `referral_activation_trigger` | text | Either ''signup'' or ''first_purchase'' - determines reward timing |\n| `referral_active` | boolean | Master switch for referral program activation |\n\n### 2. referral_inviter_limits Table\nDefines participation limits for different user types. A merchant can have different limits for buyers vs sellers:\n\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | Unique identifier for the limit configuration |\n| `merchant_id` | uuid | References merchant_master |\n| `user_type` | enum | Either ''buyer'' or ''seller'' - determines which users these limits apply to |\n| `max_referrals_per_day` | integer | Daily limit for new referrals |\n| `max_referrals_per_week` | integer | Weekly limit for new referrals |\n| `max_referrals_per_month` | integer | Monthly limit for new referrals |\n| `max_referrals_per_year` | integer | Yearly limit for new referrals |\n| `max_referrals_lifetime` | integer | Total lifetime limit for referrals |\n| `priority` | integer | Resolution order when user matches multiple types |\n| `created_at` | timestamptz | Timestamp of configuration creation |\n\n### 3. referral_invitee_outcomes Table\nDefines what rewards invitees receive when referral conditions are met:\n\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | Unique identifier for the outcome |\n| `merchant_id` | uuid | References merchant_master |\n| `outcome_type` | enum | Type of reward: ''points'', ''tickets'', or ''reward'' |\n| `entity_id` | uuid | For tickets: ticket_type_id; For rewards: reward_id; NULL for points |\n| `amount` | numeric | Quantity of points or tickets (NULL for rewards - always qty 1) |\n| `valid_for_days` | integer | Validity period after activation trigger |\n| `created_at` | timestamptz | Timestamp of outcome creation |\n\n### 4. referral_codes Table\nStores unique invite codes for each user-merchant combination:\n\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | Unique identifier |\n| `user_id` | uuid | References auth.users - the inviter |\n| `merchant_id` | uuid | References merchant_master |\n| `invite_code` | varchar | Unique 8-character alphanumeric code |\n| `created_at` | timestamptz | Timestamp of code generation |\n| **Unique Constraints** | | (user_id, merchant_id) - one code per user per merchant |\n\n### 5. referral_ledger Table\nCentral tracking table for all referral relationships and their status:\n\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | Unique identifier for the referral |\n| `merchant_id` | uuid | References merchant_master |\n| `inviter_user_id` | uuid | References auth.users - who sent the invite |\n| `invitee_user_id` | uuid | References auth.users - who accepted the invite |\n| `invite_code` | varchar | References referral_codes.invite_code used |\n| `signed_up_at` | timestamptz | When invitee registered |\n| `first_purchase_at` | timestamptz | When invitee made first purchase (if applicable) |\n| `created_at` | timestamptz | Timestamp of referral creation |\n| **Unique Constraints** | | (invitee_user_id, merchant_id) - one referral per invitee per merchant |\n\n### 6. Integration with Existing Tables\n\n#### wallet_ledger (Points/Tickets Distribution)\n- `source_type = ''referral''`: Identifies referral-sourced rewards\n- `source_id`: References referral_ledger.id for complete traceability\n- `component`: Uses ''bonus'' for points, ''base'' for tickets to handle uniqueness constraints\n- `metadata`: Stores outcome type and sequence for multiple rewards\n\n#### reward_redemptions_ledger (Physical/Digital Rewards)\n- `source_type = ''referral''`: Identifies referral-sourced rewards\n- `source_id`: References referral_ledger.id\n\n#### mission_evaluation_queue (Inviter Rewards)\n- `event_type`: New types ''referral_signup'' and ''referral_purchase''\n- `event_data`: Contains referral_ledger_id and invitee_user_id", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Referral.md#L31 Core Tables and Structure", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "referral", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "3001c1a3f0ed8b21c03c2f42017d0d39c3489a0bbd1837d54a82715dfa55a311", "truncated": false}, "is_active": true}, {"id": "f6c769a3-a12d-5ebd-89ae-37bc173b488d", "feature_slug": "referral", "title": "2. Key Concepts", "content": "**Inviter** — An existing member who shares their invite code to recruit new users. Receives rewards indirectly through the mission system. Example: Alice shares code \"XK7M2NP1\" with friends.\n\n**Invitee** — A new user who signs up using an invite code. Receives direct rewards (points, tickets, or reward items) upon activation. Each invitee can only be referred once per merchant. Example: Bob enters Alice''s code during registration.\n\n**Invite Code** — A unique 8-character alphanumeric string assigned permanently to one member per merchant. Generated lazily on first request using MD5 hash with collision detection. Once created, it never changes. Example: \"XK7M2NP1\".\n\n**Activation Trigger** — Merchant-level setting that determines when referral rewards are distributed. Two values: `signup` (rewards fire when invitee registers) or `first_purchase` (rewards fire when invitee completes their first transaction). Applies to both invitee rewards and inviter mission progress.\n\n**Invitee Outcome** — A configured reward that invitees receive upon activation. Three types: `points` (credited to wallet), `tickets` (credited to wallet), or `reward` (creates a redemption ledger record, always qty 1). Multiple outcomes can be configured — all are distributed in a single pass.\n\n**Inviter Reward** — Not a separate system. Inviters earn rewards through missions configured with `referral_signup` or `referral_purchase` conditions. The mission system counts qualifying referral_ledger records to evaluate progress.\n\n**Referral Limit** — Per-user-type caps on how many referrals an inviter can generate. Five periods: daily, weekly, monthly, yearly, lifetime. Limits are checked when the invitee signs up, not when the code is shared. Null values mean no restriction for that period.\n\n**User Type** — Either `buyer` or `seller`. Determines which set of referral limits applies. Resolved from `user_accounts` during signup processing. Sellers typically get higher limits than buyers.\n\n**Referral Ledger** — Central tracking record linking inviter, invitee, invite code, signup timestamp, and first purchase timestamp. The `first_purchase_at` field is null until the invitee makes a purchase — this is what the purchase trigger checks.", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/referral.md#L13 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "referral", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ff64521e7ae2b94e44b7bd2baf6cd964f7c583efa37896da20857eb516a90a60", "truncated": false}, "is_active": true}, {"id": "3a1a58d9-502b-5cc6-83ca-88933c215744", "feature_slug": "referral", "title": "6a. For Customer Success / Support", "content": "**Elevator pitch:** \"When your members share their invite code and someone signs up with it, both sides get rewarded. The person sharing gets progress toward referral missions. The new member gets welcome benefits like bonus points or tickets.\"\n\n**Top support questions:**\n\n| Question | Answer |\n|---|---|\n| \"My invite code doesn''t work\" | Verify `referral_active = true` on the merchant. Check if the inviter has hit their referral limit for the current period. |\n| \"I referred someone but didn''t get rewards\" | Inviter rewards come from missions. Verify a mission with `referral_signup` or `referral_purchase` condition exists. Check if the activation trigger has been met (signup vs first purchase). |\n| \"My friend signed up but I can''t see them\" | Check `referral_ledger` — the record should exist if the code was entered during signup. If missing, the invitee may not have entered the code. |\n| \"The invitee didn''t receive points\" | Verify invitee outcomes are configured. Check if the activation trigger has been met. If trigger is `first_purchase`, rewards won''t appear until the invitee buys something. |\n| \"Can I get a new invite code?\" | No — one permanent code per member. The same code works indefinitely. |", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/referral.md#L158 6. Perspectives / 6a. For Customer Success / Support", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "referral", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c848d0be34df8e13bffe724ea7f7f90e6aa38724a8cba119354ea0d8169daee5", "truncated": false}, "is_active": true}, {"id": "419d10db-0925-521f-ab06-2a06c2282b24", "feature_slug": "referral", "title": "1. Overview", "content": "Referral is a word-of-mouth acquisition channel. Existing members (inviters) share a personal invite code; new users (invitees) enter that code during signup. Both sides receive rewards — invitees get direct benefits (points, tickets, or reward items), while inviters earn progress toward referral missions. This two-sided incentive structure drives member-led growth.\n\nThe merchant controls a single activation trigger that determines when rewards fire: either at signup (immediate gratification, higher volume) or at first purchase (higher-quality leads). Invite codes are permanent — one code per member per merchant, generated on first request and reused forever. Inviter limits prevent abuse by capping referrals per day, week, month, year, and lifetime, differentiated by user type (buyer vs seller).\n\nInvitee rewards are distributed directly through the wallet and reward redemption systems. Inviter rewards are handled entirely by the mission system — merchants create missions with `referral_signup` or `referral_purchase` conditions, enabling milestone-based progressive rewards without any referral-specific reward logic.\n\n> **Frontend status:** The admin configuration UI and member-facing referral screens are not yet built. The backend (tables, functions, triggers) is fully deployed. Sections 4 and 5 describe the planned journeys based on backend capabilities.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/referral.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "referral", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "7d070a8a8d4cbb8c7a45daa44e89ef69ceb9b56d4e3c9b47dd85b117a56d1fe7", "truncated": false}, "is_active": true}, {"id": "48eec78b-e599-5507-9223-fbd23bd584ac", "feature_slug": "referral", "title": "8. Related Features", "content": "| Feature | Connection to Referral |\n|---|---|\n| Currency | Invitee point and ticket rewards are distributed through `wallet_ledger`. See `Currency.md`. |\n| Mission | Inviter rewards are delivered via missions with `referral_signup` or `referral_purchase` conditions. See `Mission.md`. |\n| Rewards | Invitee reward-type outcomes create records in `reward_redemptions_ledger`. See `Reward.md`. |\n| Signup | Invite code entry happens during the registration flow. See Signup Drawer in `loyalty-user`. |\n| Purchase | The `first_purchase` activation trigger fires via a trigger on `purchase_ledger`. See `Purchase_Transaction.md`. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/referral.md#L253 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "referral", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "596e9320363f9f6a694eb8ac9d1c84194df341d0db84d8ea6c5c3434159d5024", "truncated": false}, "is_active": true}]'::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id,
  feature_item_id,
  title,
  content,
  content_format,
  knowledge_type,
  perspectives,
  output_uses,
  scope,
  source_ref,
  metadata,
  is_active,
  now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
